def design(rng, n, p, rho):
    x = rng.normal(size=(n, p))
    if rho:
        x = np.sqrt(1 - rho) * x + np.sqrt(rho) * rng.normal(size=(n, 1)) * rng.choice([-1, 1], size=p)
    return x / np.linalg.norm(x, axis=0) * rng.uniform(1.7, 3.0, p)
